#!/usr/bin/env python3
"""Score captured agent transcripts for Brain/Graph instruction adherence.

Input: Claude Code JSONL transcripts (local projects + entire checkpoint dumps).
Output: one JSON row per session (deduped by sessionId, longest wins).
Python 3.9 compatible.
"""
import json, os, re, sys, glob

BRAIN_RE = re.compile(r"\bentire\s+brain\s+([a-z-]+)")
GRAPH_RE = re.compile(r"\bentire\s+graph\s+([a-z-]+)")
FACT_ID_RE = re.compile(r"fact:[0-9a-f]{8,}")
EXPLORE_BASH_RE = re.compile(r"^\s*(rg|grep|find|cat|head|tail|ls|fd|ag)\b")
EDIT_TOOLS = {"Edit", "Write", "MultiEdit", "NotebookEdit"}
EXPLORE_TOOLS = {"Read", "Grep", "Glob", "LS"}


def iter_lines(path):
    with open(path, "r", errors="replace") as f:
        for line in f:
            line = line.strip()
            if not line:
                continue
            try:
                yield json.loads(line)
            except Exception:
                continue


def text_of(content):
    """Flatten a message content field to text (str or block list)."""
    if isinstance(content, str):
        return content
    out = []
    if isinstance(content, list):
        for b in content:
            if isinstance(b, dict):
                if b.get("type") == "text":
                    out.append(b.get("text", ""))
                elif b.get("type") == "tool_result":
                    c = b.get("content")
                    if isinstance(c, str):
                        out.append(c)
                    elif isinstance(c, list):
                        for cc in c:
                            if isinstance(cc, dict) and cc.get("type") == "text":
                                out.append(cc.get("text", ""))
    return "\n".join(out)


def score_file(path):
    s = {
        "file": path,
        "session_id": None,
        "format": "claude",
        "cwd": None,
        "branch": None,
        "first_ts": None,
        "last_ts": None,
        "models": set(),
        "n_lines": 0,
        "n_user_prompts": 0,
        "n_tool_calls": 0,
        "n_edit_calls": 0,
        "n_explore_calls": 0,
        "n_subagent_calls": 0,
        "brain_cmds": {},          # subcommand -> count
        "graph_cmds": {},
        "mcp_brain_calls": 0,
        "first_explore_idx": None,
        "first_edit_idx": None,
        "first_brief_idx": None,
        "first_brain_idx": None,
        "first_graph_idx": None,
        "version_before_brain": False,
        "caps_before_brain": False,
        "seen_version_idx": None,
        "seen_caps_idx": None,
        "recall_facts_returned": 0,
        "brief_ran": False,
        "recall_ran": False,
        "remember_ran": False,
        "fact_ids_returned": set(),
        "fact_ids_cited_later": set(),
        "guide_in_context": False,
    }
    tool_idx = 0
    # map tool_use_id -> kind ("brief"|"recall")
    pending = {}
    saw_result_for = set()

    for e in iter_lines(path):
        s["n_lines"] += 1
        t = e.get("type")
        if t not in ("user", "assistant"):
            if t == "summary":
                continue
            # codex / other format sniff
            if t in ("response_item", "event_msg", "turn_context") or "payload" in e:
                s["format"] = "codex"
            continue
        if e.get("isSidechain"):
            continue
        ts = e.get("timestamp")
        if ts:
            if s["first_ts"] is None:
                s["first_ts"] = ts
            s["last_ts"] = ts
        if s["session_id"] is None:
            s["session_id"] = e.get("sessionId")
        if s["cwd"] is None:
            s["cwd"] = e.get("cwd")
        if e.get("gitBranch") and s["branch"] is None:
            s["branch"] = e.get("gitBranch")
        msg = e.get("message") or {}
        if t == "assistant":
            if msg.get("model"):
                s["models"].add(msg["model"])
            content = msg.get("content") or []
            if isinstance(content, list):
                for b in content:
                    if not isinstance(b, dict):
                        continue
                    if b.get("type") == "text":
                        for fid in FACT_ID_RE.findall(b.get("text", "")):
                            if fid in s["fact_ids_returned"]:
                                s["fact_ids_cited_later"].add(fid)
                    if b.get("type") != "tool_use":
                        continue
                    tool_idx += 1
                    s["n_tool_calls"] += 1
                    name = b.get("name", "")
                    inp = b.get("input") or {}
                    if name in EDIT_TOOLS:
                        s["n_edit_calls"] += 1
                        if s["first_edit_idx"] is None:
                            s["first_edit_idx"] = tool_idx
                    if name in ("Task", "Agent"):
                        s["n_subagent_calls"] += 1
                    explore = False
                    if name in EXPLORE_TOOLS:
                        explore = True
                    cmd = inp.get("command", "") if name == "Bash" else ""
                    if name == "Bash" and EXPLORE_BASH_RE.search(cmd or ""):
                        explore = True
                    if explore:
                        s["n_explore_calls"] += 1
                        if s["first_explore_idx"] is None:
                            s["first_explore_idx"] = tool_idx
                    brain_sub = None
                    graph_sub = None
                    if cmd:
                        m = BRAIN_RE.search(cmd)
                        if m:
                            brain_sub = m.group(1)
                        m = GRAPH_RE.search(cmd)
                        if m:
                            graph_sub = m.group(1)
                    if name.startswith("mcp__") and "brain" in name.lower():
                        s["mcp_brain_calls"] += 1
                        brain_sub = brain_sub or name.split("__")[-1]
                    if brain_sub:
                        s["brain_cmds"][brain_sub] = s["brain_cmds"].get(brain_sub, 0) + 1
                        if s["first_brain_idx"] is None:
                            s["first_brain_idx"] = tool_idx
                        if brain_sub == "version":
                            s["seen_version_idx"] = s["seen_version_idx"] or tool_idx
                        if brain_sub == "capabilities":
                            s["seen_caps_idx"] = s["seen_caps_idx"] or tool_idx
                        if brain_sub == "brief":
                            s["brief_ran"] = True
                            if s["first_brief_idx"] is None:
                                s["first_brief_idx"] = tool_idx
                            pending[b.get("id")] = "brief"
                        if brain_sub == "recall":
                            s["recall_ran"] = True
                            pending[b.get("id")] = "recall"
                        if brain_sub == "remember":
                            s["remember_ran"] = True
                    if graph_sub:
                        s["graph_cmds"][graph_sub] = s["graph_cmds"].get(graph_sub, 0) + 1
                        if s["first_graph_idx"] is None:
                            s["first_graph_idx"] = tool_idx
        else:  # user
            content = msg.get("content")
            if isinstance(content, list):
                has_tool_result = False
                for b in content:
                    if isinstance(b, dict) and b.get("type") == "tool_result":
                        has_tool_result = True
                        tid = b.get("tool_use_id")
                        if tid in pending and tid not in saw_result_for:
                            saw_result_for.add(tid)
                            txt = text_of([b])
                            fids = FACT_ID_RE.findall(txt)
                            s["fact_ids_returned"].update(fids)
                            if pending[tid] == "recall":
                                s["recall_facts_returned"] += len(set(fids))
                if not has_tool_result and not e.get("isMeta"):
                    txt = text_of(content)
                    if txt and not txt.startswith("<"):
                        s["n_user_prompts"] += 1
                    if "agent-guide.md" in txt or "entire brain brief" in txt:
                        s["guide_in_context"] = True
            elif isinstance(content, str):
                if not e.get("isMeta"):
                    if content and not content.startswith("<"):
                        s["n_user_prompts"] += 1
                    if "agent-guide.md" in content or "entire brain brief" in content:
                        s["guide_in_context"] = True

    # derived
    fb = s["first_brain_idx"]
    s["version_before_brain"] = bool(
        s["seen_version_idx"] is not None and (fb is None or s["seen_version_idx"] <= fb + 2)
    )
    s["caps_before_brain"] = bool(
        s["seen_caps_idx"] is not None and (fb is None or s["seen_caps_idx"] <= fb + 2)
    )
    s["models"] = sorted(s["models"])
    s["fact_ids_returned"] = sorted(s["fact_ids_returned"])
    s["fact_ids_cited_later"] = sorted(s["fact_ids_cited_later"])
    return s


def main():
    out = {}
    paths = []
    for arg in sys.argv[1:]:
        if os.path.isdir(arg):
            paths.extend(glob.glob(os.path.join(arg, "*.jsonl")))
        else:
            paths.append(arg)
    for p in paths:
        try:
            row = score_file(p)
        except Exception as ex:
            sys.stderr.write("ERR %s: %s\n" % (p, ex))
            continue
        sid = row["session_id"] or row["file"]
        prev = out.get(sid)
        if prev is None or row["n_lines"] > prev["n_lines"]:
            out[sid] = row
    for row in out.values():
        print(json.dumps(row))


if __name__ == "__main__":
    main()

#!/usr/bin/env python3
"""Segment sessions into meta (developing brain/graph features) vs non-meta,
using the first real user prompt, and re-print adherence per segment."""
import json, sys, re

META_RE = re.compile(
    r"\b(brain|memor(y|ies)|recall|distill|durable fact|graph|checkpoint|agent.guide|adherence|benchmark)\b",
    re.I,
)


def first_prompt(path):
    try:
        with open(path, errors="replace") as f:
            for line in f:
                try:
                    e = json.loads(line)
                except Exception:
                    continue
                if e.get("type") != "user" or e.get("isSidechain") or e.get("isMeta"):
                    continue
                c = (e.get("message") or {}).get("content")
                if isinstance(c, str) and c and not c.startswith("<"):
                    return c[:2000]
                if isinstance(c, list):
                    txts = [b.get("text", "") for b in c if isinstance(b, dict) and b.get("type") == "text"]
                    t = "\n".join(txts).strip()
                    if t and not t.startswith("<") and "tool_result" not in str([b.get("type") for b in c if isinstance(b, dict)]):
                        return t[:2000]
    except Exception:
        pass
    return ""


rows = {}
for path in sys.argv[1:]:
    for line in open(path):
        r = json.loads(line)
        sid = r["session_id"] or r["file"]
        prev = rows.get(sid)
        if prev is None or r["n_lines"] > prev["n_lines"]:
            rows[sid] = r

subst = [r for r in rows.values() if r["n_tool_calls"] >= 5 and r["n_user_prompts"] >= 1]
for r in subst:
    p = first_prompt(r["file"])
    r["prompt_head"] = p[:160].replace("\n", " ")
    r["meta"] = bool(META_RE.search(p))


def pct(n, d):
    return "%d/%d (%.0f%%)" % (n, d, 100.0 * n / d) if d else "0/0"


for label in (True, False):
    rs = [r for r in subst if r["meta"] == label]
    n = len(rs)
    print("=== %s sessions: %d ===" % ("META (brain/graph feature work)" if label else "NON-META (ordinary coding)", n))
    if not n:
        continue
    print("brief ran:        ", pct(sum(1 for r in rs if r["brief_ran"]), n))
    print("brief before expl:", pct(sum(1 for r in rs if r["brief_ran"] and (r["first_explore_idx"] is None or (r["first_brief_idx"] or 1e9) <= r["first_explore_idx"])), n))
    print("recall ran:       ", pct(sum(1 for r in rs if r["recall_ran"]), n))
    print("remember ran:     ", pct(sum(1 for r in rs if r["remember_ran"]), n))
    print("graph used:       ", pct(sum(1 for r in rs if r["graph_cmds"]), n))
    wf = [r for r in rs if r["fact_ids_returned"]]
    print("facts returned:   ", pct(len(wf), n))
    print("facts cited later:", pct(sum(1 for r in wf if r["fact_ids_cited_later"]), len(wf)))
    print()

# dump non-meta prompts for inspection + sample for hand-labeling
with open("nonmeta_sessions.tsv", "w") as f:
    for r in subst:
        if not r["meta"]:
            f.write("%s\t%s\t%s\n" % (r["session_id"], r["file"], r["prompt_head"]))
with open("recall_sessions.tsv", "w") as f:
    for r in subst:
        if r["fact_ids_returned"]:
            f.write("%s\t%d\t%d\t%s\t%s\n" % (r["session_id"], len(r["fact_ids_returned"]), len(r["fact_ids_cited_later"]), "META" if r["meta"] else "NONMETA", r["file"]))
print("wrote nonmeta_sessions.tsv and recall_sessions.tsv")

