                continue
            if e.get("type") not in ("user", "assistant") or e.get("isSidechain"):
                continue
            msg = e.get("message") or {}
            c = msg.get("content")
            if e.get("type") == "user":
                if isinstance(c, list) and any(isinstance(b, dict) and b.get("type") == "tool_result" for b in c):
                    for b in c:
                        if isinstance(b, dict) and b.get("type") == "tool_result" and b.get("tool_use_id") in pending:
                            kind = pending.pop(b["tool_use_id"])
                            events.append(("RESULT(%s)" % kind, text_of([b])[:LIM_RESULT]))
                            want_next_text = 2
                elif not e.get("isMeta"):
                    t = text_of(c)
                    if t and not t.startswith("<") and first_prompt is None:
                        first_prompt = t[:2000]
            else:
                if isinstance(c, list):
                    for b in c:
                        if not isinstance(b, dict):
                            continue
                        if b.get("type") == "text" and b.get("text", "").strip():
                            last_assistant = b.get("text")
                            if want_next_text > 0:
                                events.append(("AGENT-TEXT-AFTER", b["text"][:LIM_TEXT]))
                                want_next_text -= 1
                        if b.get("type") == "tool_use":
                            cmd = (b.get("input") or {}).get("command", "")
                            if "entire brain brief" in cmd:
                                pending[b.get("id")] = "brief"
                                events.append(("CALL", cmd[:400]))
                            elif "entire brain recall" in cmd:
                                pending[b.get("id")] = "recall"
                                events.append(("CALL", cmd[:400]))
    with open(out_path, "w") as f:
        f.write("# %s\n\n## TASK PROMPT\n%s\n\n" % (os.path.basename(path), first_prompt or "(none)"))
        for kind, txt in events:
            f.write("## %s\n%s\n\n" % (kind, txt))
        f.write("## FINAL ASSISTANT TEXT\n%s\n" % (last_assistant or "")[:2500])


os.makedirs("digests", exist_ok=True)
for line in open(sys.argv[1]):
    sid, nret, ncit, seg, path = line.rstrip("\n").split("\t")
    out = os.path.join("digests", "%s_%s_%s.md" % (seg, nret, (sid or "x")[:8]))
    try:
        digest(path, out)
    except Exception as ex:
        sys.stderr.write("ERR %s: %s\n" % (path, ex))
print("done")

