#!/usr/bin/env python3
"""Score headless A/B runs (claude -p stream-json). One row per run file."""
import json, os, re, sys, glob

BRAIN_RE = re.compile(r"\bentire\s+brain\s+([a-z-]+)")
GRAPH_RE = re.compile(r"\bentire\s+graph\s+([a-z-]+)")
EXPLORE_BASH_RE = re.compile(r"^\s*(rg|grep|find|cat|head|tail|ls|fd|ag)\b")
EXPLORE_TOOLS = {"Read", "Grep", "Glob", "LS"}
EDIT_TOOLS = {"Edit", "Write", "MultiEdit", "NotebookEdit"}

MARKERS = {
    "T1": re.compile(r"0\.34|96,?987|TestNormalGuideStaysDirective|self-assessed exits?|2026-09-14|graph-first rate", re.I),
    "T2": re.compile(r"agent_wiring|InstallChanged|EnsureAgentWiring", re.I),
    "T4": re.compile(r"updateFactSourceManifestLocked|loadAllFactBranches|O\(total facts\)|all branches.*(rewrite|parse)", re.I),
    "T5": re.compile(r"(trail\s*#?278|model2vec|removed.*(semantic|vector|embedd)|(semantic|vector|embedd).*removed)", re.I),
}


def score(path):
    base = os.path.basename(path).replace(".jsonl", "")
    parts = base.split("-")  # ab-<arm>-<task>-r<rep>
    arm, task, rep = parts[1], parts[2], parts[3]
    r = {
        "run": base, "arm": arm, "task": task, "rep": rep,
        "tool_calls": 0, "explore": 0, "edits": 0,
        "brief": 0, "recall": 0, "recall_branch": 0, "remember": 0,
        "graph_q": 0, "impact": 0, "brain_other": 0,
        "first_brief_idx": None, "first_explore_idx": None,
        "turns": None, "cost": None, "dur_s": None, "final": "", "ok": None,
    }
    idx = 0
    for line in open(path, errors="replace"):
        try:
            e = json.loads(line)
        except Exception:
            continue
        t = e.get("type")
        if t == "result":
            r["turns"] = e.get("num_turns")
            r["cost"] = e.get("total_cost_usd")
            r["dur_s"] = round((e.get("duration_ms") or 0) / 1000)
            r["final"] = (e.get("result") or "")[:4000]
        if t != "assistant":
            continue
        for b in (e.get("message") or {}).get("content") or []:
            if not isinstance(b, dict) or b.get("type") != "tool_use":
                continue
            idx += 1
            r["tool_calls"] += 1
            name = b.get("name", "")
            inp = b.get("input") or {}
            cmd = inp.get("command", "") if name == "Bash" else ""
            if name in EDIT_TOOLS:
                r["edits"] += 1
            if name in EXPLORE_TOOLS or (cmd and EXPLORE_BASH_RE.search(cmd)):
                r["explore"] += 1
                if r["first_explore_idx"] is None:
                    r["first_explore_idx"] = idx
            m = BRAIN_RE.search(cmd or "")
            if m:
                sub = m.group(1)
                if sub == "brief":
                    r["brief"] += 1
                    if r["first_brief_idx"] is None:
                        r["first_brief_idx"] = idx
                elif sub == "recall":
                    r["recall"] += 1
                    if "--branch" in cmd:
                        r["recall_branch"] += 1
                elif sub == "remember":
                    r["remember"] += 1
                else:
                    r["brain_other"] += 1
            m = GRAPH_RE.search(cmd or "")
            if m:
                if m.group(1) == "impact":
                    r["impact"] += 1
                elif m.group(1) in ("query", "neighbors", "search", "context", "def"):
                    r["graph_q"] += 1
    mk = MARKERS.get(r["task"])
    if mk is not None:
        r["ok"] = bool(mk.search(r["final"]))
    r["brief_first"] = bool(
        r["brief"] and (r["first_explore_idx"] is None or (r["first_brief_idx"] or 10 ** 9) <= r["first_explore_idx"])
    )
    return r


rows = [score(p) for p in sorted(glob.glob(sys.argv[1]))]
cols = ["run", "brief", "brief_first", "recall", "recall_branch", "graph_q", "impact", "remember", "explore", "edits", "tool_calls", "turns", "dur_s", "cost", "ok"]
print("\t".join(cols))
for r in rows:
    print("\t".join(str(r[c]) for c in cols))
with open("run_rows.json", "w") as f:
    json.dump(rows, f, indent=1)

#!/usr/bin/env python3
"""Count friction signals in recall/brief usage across raw transcripts."""
import json, re, sys, glob, os

counters = {
    "recall_calls": 0,
    "recall_empty": 0,        # facts [] or null in a recall result
    "recall_branch_flag": 0,  # recall invoked with --branch
    "recall_truncated": 0,    # piped through head -c
    "brief_calls": 0,
    "brief_truncated": 0,
    "brain_locked_results": 0,
    "manifest_warning_results": 0,
    "dup_fact_warning_results": 0,
    "hardlink_error_results": 0,
    "no_memories_branch_warning": 0,
}
sessions_with_empty_then_branch_retry = 0
sessions_with_empty_no_retry = 0

EMPTY_RE = re.compile(r'"facts":\s*(\[\]|null)')


def handle(path):
    global sessions_with_empty_then_branch_retry, sessions_with_empty_no_retry
    pending = {}
    saw_empty = False
    saw_branch_retry_after_empty = False
    for line in open(path, errors="replace"):
        try:
            e = json.loads(line)
        except Exception:
            continue
        t = e.get("type")
        if t == "assistant":
            for b in (e.get("message") or {}).get("content") or []:
                if isinstance(b, dict) and b.get("type") == "tool_use" and b.get("name") == "Bash":
                    cmd = (b.get("input") or {}).get("command", "") or ""
                    if "entire brain recall" in cmd:
                        counters["recall_calls"] += 1
                        pending[b.get("id")] = "recall"
                        if "--branch" in cmd:
                            counters["recall_branch_flag"] += 1
                            if saw_empty:
                                saw_branch_retry_after_empty = True
                        if re.search(r"head -c\s*\d+", cmd):
                            counters["recall_truncated"] += 1
                    elif "entire brain brief" in cmd:
                        counters["brief_calls"] += 1
                        pending[b.get("id")] = "brief"
                        if re.search(r"head -c\s*\d+", cmd):
                            counters["brief_truncated"] += 1
        elif t == "user":
            c = (e.get("message") or {}).get("content")
            if not isinstance(c, list):
                continue
            for b in c:
                if not isinstance(b, dict) or b.get("type") != "tool_result":
                    continue
                kind = pending.pop(b.get("tool_use_id"), None)
                if kind is None:
                    continue
                txt = b.get("content")
                if isinstance(txt, list):
                    txt = "\n".join(x.get("text", "") for x in txt if isinstance(x, dict))
                txt = txt or ""
                if kind == "recall" and EMPTY_RE.search(txt):
                    counters["recall_empty"] += 1
                    saw_empty = True
                if "brain_locked" in txt:
                    counters["brain_locked_results"] += 1
                if "manifest is behind" in txt or "does not match the manifest" in txt:
                    counters["manifest_warning_results"] += 1
                if "duplicate" in txt and "fact" in txt:
                    counters["dup_fact_warning_results"] += 1
                if "must not be hardlinked" in txt:
                    counters["hardlink_error_results"] += 1
                if "no memories on branch" in txt:
                    counters["no_memories_branch_warning"] += 1
    if saw_empty:
        if saw_branch_retry_after_empty:
            sessions_with_empty_then_branch_retry += 1
        else:
            sessions_with_empty_no_retry += 1


files = []
for arg in sys.argv[1:]:
    if os.path.isdir(arg):
        files.extend(glob.glob(os.path.join(arg, "*.jsonl")))
    elif arg.endswith(".txt"):
        files.extend(l.strip() for l in open(arg) if l.strip())
    else:
        files.append(arg)
for p in files:
    try:
        handle(p)
    except Exception as ex:
        sys.stderr.write("ERR %s: %s\n" % (p, ex))

for k, v in counters.items():
    print("%-32s %d" % (k, v))
print("%-32s %d" % ("sessions empty->branch retry", sessions_with_empty_then_branch_retry))
print("%-32s %d" % ("sessions empty, NO retry", sessions_with_empty_no_retry))

